values ('saigon-opera-house', 'ChIJKcrnSUYvdTERO64MErYx9VU', 'Saigon Opera House', 'Nhà hát Thành phố', 'out', false, array['culture']::text[],
  'Đồng Khởi, D1', 'Đồng Khởi, Q1', '07 Công trường Lam Sơn, Sài Gòn, Hồ Chí Minh 700000, Vietnam', 10.776612799999999, 106.7031715, 4.6, 17757,
  null, '0₫', 0, 20, 40,
  'Flamboyant 1900 French opera house — catch the À Ố Show inside, or just admire the façade with a coffee across the street.', 'Nhà hát Pháp năm 1900 lộng lẫy — xem À Ố Show bên trong, hoặc ngắm mặt tiền với ly cà phê phía đối diện.', '🎭', '["Monday: 9:00 AM – 5:00 PM","Tuesday: 9:00 AM – 5:00 PM","Wednesday: 9:00 AM – 5:00 PM","Thursday: 9:00 AM – 5:00 PM","Friday: 9:00 AM – 5:00 PM","Saturday: 9:00 AM – 5:00 PM","Sunday: 9:00 AM – 5:00 PM"]'::jsonb, 'https://ticket-stations.com/a-o-show', null, 2, true, now())
